package com.luisdavid.clientservice.adapter.input.web.controller;
import com.luisdavid.clientservice.application.dto.request.CreateClientRequest; import com.luisdavid.clientservice.application.dto.response.ClientResponse; import com.luisdavid.clientservice.application.port.input.IClientUseCase; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/clients") public class ClientController { private final IClientUseCase useCase; public ClientController(IClientUseCase u){useCase=u;} @PostMapping public ResponseEntity<ClientResponse> createClient(@Valid @RequestBody CreateClientRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(useCase.createClient(r));} @GetMapping("/{id}") public ClientResponse getClientById(@PathVariable Long id){return useCase.getClientById(id);}@GetMapping public List<ClientResponse> getAllClients(){return useCase.getAllClients();}}
